cypress_script:
describe('Contact Form', () => {
  it('should submit the contact form successfully with valid data', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="name"]').type('Test User');
    cy.get('input[name="email"]').type('testuser@example.com');
    cy.get('input[name="subject"]').type('Test Subject');
    cy.get('textarea#message').type('This is a test message.');
    cy.get('input[name="submit"]').click();
    cy.url().should('include', '/contact_us');
    cy.get('div#success-subscribe').should('be.visible');
  });

  it('should not submit the contact form with empty fields', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="submit"]').click();
    cy.url().should('include', '/contact_us');
    cy.get('div#contact-page').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Contact Form', () => {
  test('should submit the contact form successfully with valid data', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.fill('input[name="name"]', 'Test User');
    await page.fill('input[name="email"]', 'testuser@example.com');
    await page.fill('input[name="subject"]', 'Test Subject');
    await page.fill('textarea#message', 'This is a test message.');
    await page.click('input[name="submit"]');
    await expect(page).toHaveURL(/.*contact_us/);
    await expect(page.locator('div#success-subscribe')).toBeVisible();
  });

  test('should not submit the contact form with empty fields', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.click('input[name="submit"]');
    await expect(page).toHaveURL(/.*contact_us/);
    await expect(page.locator('div#contact-page')).toBeVisible();
  });
});
